"""Build a working thesis manuscript from verified project artifacts.

Deliberately labels unfinished annotation, external evaluation and university
formatting. This is not a claim that the dissertation is ready for submission.
"""
import argparse
import html
import json
import os
from pathlib import Path
from kazstyle.data.corpus import load_manifest,write_json,file_hash
from kazstyle.settings import PROJECT_ROOT,evidence_path
from kazstyle.inference.deployment import FAMILIES


def expanded_chapter(summary,out):
    evidence=json.loads((summary/'provenance.json').read_text(encoding='utf-8'))
    protocol_path=evidence_path(evidence['suite'])/'protocol.json'
    protocol=json.loads(protocol_path.read_text(encoding='utf-8'))
    frame,config=load_manifest(PROJECT_ROOT/protocol['plan']['dataset'])
    if config['manifest_sha256']!=evidence['manifest_sha256']:raise ValueError('Expanded manuscript dataset differs')
    results=json.loads((summary/'results.json').read_text(encoding='utf-8'))
    selection=json.loads((summary/'selection.json').read_text(encoding='utf-8'))
    rows=[]
    for family,(_,name,_) in FAMILIES.items():
        r=results[family]
        rows.append('<tr><td>'+html.escape(name)+'</td><td>'+f"{r['validation_macro_f1_mean']:.4f} ± {r['validation_macro_f1_sample_std']:.4f}"+'</td><td>'+f"{r['test_macro_f1_mean']:.4f} ± {r['test_macro_f1_sample_std']:.4f}"+'</td></tr>')
    table='<table><tr><th>Модель</th><th>Validation Macro-F1</th><th>Внутренний test Macro-F1</th></tr>'+''.join(rows)+'</table>'
    holdout=summary.parent/'source_holdout'
    values=json.loads((holdout/'results.json').read_text(encoding='utf-8'))
    hrows=''.join('<tr><td>'+html.escape(FAMILIES[n][1])+'</td><td>'+f"{r['validation_macro_f1']:.4f}"+'</td><td>'+f"{r['test']['macro_f1']:.4f}"+'</td></tr>' for n,r in values.items() if n!='dummy_prior')
    htable='<table><tr><th>Отдельно обученная модель</th><th>Validation</th><th>Отложенные источники</th></tr>'+hrows+'</table>'
    figures=summary.parent/'figures'
    imgs=''.join('<figure><img style="width:100%;height:auto" src="'+html.escape(Path(os.path.relpath(figures/(name+'.png'),out)).as_posix(),quote=True)+'" alt="'+html.escape(caption,quote=True)+'"><figcaption>'+caption+'</figcaption></figure>' for name,caption in [('macro_f1_three_seeds','Рисунок 5.1. Внутренний test v6: среднее и разброс трёх seed.'),('confusion_matrices_seed42','Рисунок 5.2. Матрицы ошибок v6, фиксированный seed 42.')])
    template=Path(__file__).with_name('manuscript_expanded.html')
    content=template.read_text(encoding='utf-8')
    replacements={'SOURCE_TABLE':frame.groupby(['style_name','source_domain','split']).size().unstack(fill_value=0).to_html(),
        'RESULTS_TABLE':table,'SOURCE_HOLDOUT_TABLE':htable,'DEFAULT_FAMILY':html.escape(FAMILIES[selection['family']][1]),
        'FIGURES':imgs,'DATASET_SHA':config['manifest_sha256']}
    for key,value in replacements.items():content=content.replace('{{'+key+'}}',value)
    if '{{' in content:raise ValueError('Unresolved manuscript placeholder')
    literature=PROJECT_ROOT/'configs/literature_sources.json'
    sources=json.loads(literature.read_text(encoding='utf-8'))['sources']
    content+='<h3>Источники расширенного раздела</h3><ol>'+''.join('<li>'+html.escape('; '.join(r['authors']))+'. '+html.escape(r['title'])+'. '+html.escape(str(r.get('year') or 'б. г.'))+'. <a href="'+html.escape(r['url'],quote=True)+'">Первичный источник</a>.</li>' for r in sources)+'</ol><p>Проверены метаданные и аннотации; подробные положения полного обзора требуют чтения полных текстов.</p>'
    files=[summary/'provenance.json',summary/'results.json',summary/'bootstrap.json',summary/'selection.json',holdout/'results.json',holdout/'COMPLETE.json',summary.parent/'length_ablation/results.json',summary.parent/'length_ablation/COMPLETE.json',summary.parent/'deployment_gate.json',template,literature]
    return content,{str(p):file_hash(p) for p in files}


def build(out,results=None,expanded=None):
    if out.exists():raise FileExistsError(out)
    dataset=PROJECT_ROOT/'data/processed/text_only_v4_shared'
    frame,config=load_manifest(dataset)
    plan=json.loads((PROJECT_ROOT/'configs/experiment_text_only_v4.json').read_text(encoding='utf-8'))
    sections=[]
    def section(title,text):sections.append((title,text))
    section('Статус рабочей рукописи','''<div class="pending">Рабочий текст на русском языке. Это основа введения, методики, описания системы и обсуждения ограничений. Независимая экспертная разметка, окончательный внешний test, полный литературный обзор и оформление по шаблону AITU ещё не завершены. Неполученные результаты не заменяются предполагаемыми числами. Титульный лист, аннотации и окончательное заключение подготавливаются после уточнения требований университета.</div>''')
    section('Введение','''
<p>Автоматическое определение функционального стиля казахского текста связывает задачи корпусной лингвистики и машинного обучения. Практическая система должна отличать официальное заявление от новостного сообщения, научное объяснение от обсуждения научной темы и литературное повествование от повседневной переписки. При этом один и тот же предмет может описываться разными стилями. Следовательно, предметная лексика и адрес публикации не являются достаточным основанием для определения целевого класса.</p>
<p>Построение классификатора начинается с определения единицы наблюдения и правил разметки. Данные из интернета неоднородны: страницы содержат навигацию, рекламные блоки, подписи, ссылки, повторяющиеся публикации и тексты разных языков. Автоматическое присвоение метки всем материалам одного сайта создаёт риск подмены целевой задачи распознаванием источника. Даже после удаления адреса сайта характерные формулировки, длина и жанровый состав могут сохранять связь между источником и классом.</p>
<p>Поэтому в данной работе качество системы рассматривается совместно с качеством корпуса и протокола оценки. Высокая метрика на случайно выделенной части данных недостаточна, если обучающая и тестовая выборки содержат близкие фрагменты одного документа либо отражают одинаковые особенности небольшого числа источников. Исследование предусматривает документирование происхождения, группировку связанных текстов, единые входные фрагменты для сравниваемых моделей и отдельный анализ ошибок.</p>
<p><strong>Цель работы</strong> — построение корпуса казахских текстов с разметкой функционального стиля и разработка воспроизводимой системы классификации на основе методов машинного обучения. <strong>Объект исследования</strong> — казахские тексты официально-делового, научного, публицистического, художественного и разговорного стилей. <strong>Предмет исследования</strong> — методы подготовки и проверки корпуса, представления текстов, обучения классификаторов и оценки их устойчивости к изменениям источника и характеристик входного текста.</p>
<p>Для достижения цели поставлены задачи: проанализировать существующие методы и ресурсы; собрать тексты разных функциональных стилей; разработать правила разметки и проверить её согласованность; реализовать очистку и токенизацию; сравнить линейные модели и pretrained encoder-модели; разработать сервер и интерфейс; исследовать качество и ошибки; представить полученные результаты в научных материалах. Лемматизация и морфологический анализ рассматриваются в отдельном эксперименте; их эффект оценивается независимо от основной серии моделей.</p>
<p>Работа не основывается на утверждении о первом казахском корпусе пяти стилей. В исследовании Makhambetov et al. уже описан корпус, охватывающий соответствующие жанровые категории <a href="#r1">[1]</a>. Планируемый исследовательский вклад настоящей работы состоит в воспроизводимой подготовке и проверке собственного корпуса, сопоставлении разных представлений текста и анализе ограничений оценки на новых источниках. Утверждения об устойчивости системы могут быть сформулированы как результаты только после завершения соответствующих проверок.</p>
<p>Практический результат представляет собой локальную систему: пользователь вводит казахский текст, сервер выполняет предобработку и возвращает предполагаемый стиль. Система позволяет сравнивать ответы нескольких обученных вариантов и показывает фактически анализируемый фрагмент. Такой интерфейс служит средством исследования ошибок; он не заменяет количественную оценку на размеченном контрольном наборе.</p>''')
    section('1. Постановка задачи и основания выбора методов','''
<h3>1.1. Функциональный стиль как целевая переменная</h3>
<p>В принятой постановке каждому пригодному для классификации фрагменту сопоставляется один из пяти стилей. Решение определяется основной коммуникативной функцией текста. Для официально-делового стиля существенны закрепление правил, прав, обязанностей или официального запроса; для научного — последовательное объяснение понятий, методов и результатов; для публицистического — освещение и обсуждение общественно значимых событий; для художественного — литературное изображение событий и персонажей; для разговорного — непосредственное неофициальное общение.</p>
<p>Данные определения являются рабочей схемой разметки исследования и требуют проверки на пограничных случаях. Научная терминология может встречаться в новости, а официальные лица — в художественном произведении. Разговорный текст может быть длинным и грамматически правильным. Сведения об источнике используются для аудита, но не должны заранее определять решение разметчика.</p>
<p>При сборе и экспертной проверке допускаются дополнительные решения: смешанный стиль, недостаточный контекст, преимущественно другой язык и мусор. Эти решения не являются дополнительными классами текущего пятиклассового классификатора. Они позволяют не принуждать разметчика к выбору заведомо ненадёжной метки. В финальном корпусе следует отдельно зафиксировать политику включения и исключения таких примеров.</p>
<p>Ещё один существующий ресурс — основной корпус Национального корпуса казахского языка. Его официальное описание перечисляет пять стилей, поиск по метаданным и морфологическую аннотацию <a href="#r9">[9]</a>. Это важный материал для сопоставления схем разметки. Доступность поискового интерфейса сама по себе не означает наличие разрешённого для скачивания набора с фиксированными train/test; тексты этого ресурса в текущий эксперимент не импортировались.</p>
<h3>1.2. Линейные модели и контекстные представления</h3>
<p>Базовый подход использует TF-IDF для представления текста через частоты словесных или символьных n-грамм с учётом их распространённости в обучающем корпусе. Полученный вектор подаётся классификатору — логистической регрессии или линейной машине опорных векторов. Таким образом, TF-IDF является способом получения признаков, а сочетание векторизатора с классификатором образует полный обучаемый pipeline. Словарь и статистики IDF вычисляются только на train.</p>
<p>Символьные n-граммы позволяют использовать части слов и орфографические особенности без предварительного сведения слов к леммам. В данной работе это рассматривается как практический baseline для агглютинативного языка, но не как доказательство полноценного морфологического анализа. Его преимущество или недостаток относительно других представлений устанавливается экспериментально.</p>
<p>В BERT контекстные представления формируются pretrained двунаправленным encoder, который затем можно дообучать для конкретной задачи классификации <a href="#r2">[2]</a>. RoBERTa исследует изменения режима предобучения BERT и показывает значимость условий обучения при сопоставлении моделей <a href="#r3">[3]</a>. В настоящем проекте используются готовые pretrained веса; обучение языковых моделей с нуля не выполняется.</p>
<p>Выбранный Kaz-RoBERTa и многоязычный BERT различаются не только языковым охватом, но и архитектурой, словарём и токенизацией. Поэтому наблюдаемую разницу нельзя приписывать единственной причине, например наличию казахского предобучения. Сравнение последнего слоя Kaz-RoBERTa с объединением четырёх слоёв является более узким исследованием способа представления текста внутри одной модели.</p>
<p>Вопрос переноса на разные языки и веб-регистры рассматривается в работах по multilingual register classification <a href="#r4">[4]</a>. Эти исследования близки по постановке оценки регистра, однако их таксономии и корпуса не тождественны пяти стилям данной диссертации. Числа из таких работ не используются как напрямую сопоставимые показатели качества.</p>
<div class="pending">Для завершения главы требуется расширенный обзор казахской стилистики, ресурсов и методов с проверкой первоисточников; отдельное обоснование выбранных границ классов совместно со специалистом по казахскому языку.</div>''')
    section('1.3. Формальное описание реализованных классификаторов','''
<p>Пусть D = {(tᵢ, yᵢ)} — обучающая совокупность фрагментов, где tᵢ является очищенной строкой, а yᵢ принимает одно из пяти значений. Классификатор реализует функцию f(t), возвращающую предполагаемый стиль. Источник sᵢ, адрес публикации, идентификатор родительского документа и принадлежность к split сохраняются для аудита, но не входят в аргументы этой функции. Важно различать строку tᵢ, числовое представление xᵢ и сам алгоритм принятия решения.</p>
<p>Для линейных моделей представление x строится векторизатором TF-IDF. В фактической конфигурации используется логарифмическое преобразование частот: при tfⱼ &gt; 0 величина uⱼ = (1 + ln(tfⱼ)) · (1 + ln((1 + N)/(1 + dfⱼ))). Здесь N — число train-фрагментов, dfⱼ — число train-фрагментов с признаком j. Если признак отсутствует, его вес равен нулю. Затем ненулевой вектор нормируется: x = u/‖u‖₂. Формула соответствует включённым sublinear_tf и smooth_idf и нормировке L2 в scikit-learn <a href="#r10">[10]</a>.</p>
<p>В словесных вариантах признаками служат отдельные токены и последовательности из двух токенов; признаки, встретившиеся менее чем в двух train-документах, исключаются. Максимум словаря равен 80 000. В символьном варианте используются последовательности из 3–5 символов с максимумом 100 000 признаков. Эти пределы являются настройками, а не утверждением о фактическом числе признаков каждого запуска. Сохранённый векторизатор фиксирует точный словарь.</p>
<p>Векторизатор не удаляет осмысленную пунктуацию и числа из исходной строки специально ради получения нужного ответа. Символьное представление может включать пробелы и знаки препинания. Это позволяет использовать оформление диалога и окончания слов, но одновременно допускает зависимость от формата даты, имени или редакционного шаблона. Наблюдаемое влияние таких признаков отдельно проверяется в анализе ошибок.</p>
<p>Логистическая регрессия сопоставляет каждому классу оценку z꜀ = w꜀ᵀx + b꜀ и использует многоклассовую вероятностную модель. Предсказанием становится класс с максимальной оценкой. В эксперименте задано C = 1 и до 2000 итераций оптимизации. Вероятности этой модели не выводятся пользователю как доказанная уверенность: отдельная проверка калибровки не проводилась.</p>
<p>Линейный SVM также строит оценки w꜀ᵀx + b꜀, однако обучается с иной функцией потерь. Используемая реализация LinearSVC по умолчанию применяет squared hinge loss, L2-регуляризацию и схему «один класс против остальных»; задано C = 1 <a href="#r11">[11]</a>. Значение decision_function является оценкой для выбора класса, а не вероятностью. Одинаковый TF-IDF можно сочетать с разными классификаторами, поэтому выражение «TF-IDF + SVM» обозначает полный pipeline, а не два конкурирующих ответа на один текст.</p>
<p>В нейросетевых вариантах encoder преобразует последовательность токенов длины L в матрицу контекстных представлений Hᵏ размерности L × 768 на слое k. Для варианта last используется вектор первого специального токена последнего слоя: h = Hᴷ₀. Для concat4 четыре вектора первого токена объединяются в порядке от слоя K − 3 до K: h = [Hᴷ⁻³₀; Hᴷ⁻²₀; Hᴷ⁻¹₀; Hᴷ₀]. Полученная размерность равна 3072. Это конкатенация, а не усреднение слоёв.</p>
<p>После dropout с вероятностью 0,1 вектор h подаётся в линейную голову с пятью выходами. При обучении минимизируется многоклассовая cross-entropy; обновляются параметры encoder и головы. Классификатор опирается на первый специальный токен, контекст которого формируется по доступному фрагменту с учётом attention mask. Веса встроенного pooler для выбора стиля не используются. Такой способ агрегации задан реализацией и не заявляется как новая универсальная архитектура.</p>
<p>Выход системы ограничен пятью классами. В обучении нет отдельной метки «неизвестный стиль», а отказ от ответа по калиброванному порогу пока не реализован. Поэтому на смешанном, иноязычном или недостаточно содержательном тексте система может вернуть один из пяти стилей. Предупреждение о коротком вводе и расхождения между моделями помогают заметить проблему, но не заменяют отдельную оценку на таких входах.</p>''')
    section('2. Построение и проверка пилотного корпуса v4','''
<h3>2.1. Единицы данных и происхождение</h3>
<p>В реализации разделены исходный документ, кандидат на включение и фрагмент, подаваемый модели. Один документ не становится несколькими независимыми наблюдениями только потому, что его текст разбит на части. Для каждого элемента сохраняются идентификатор, адрес и домен источника, связь с родительским документом, способ получения предварительной метки и статус проверки. У текстов из общего Telegram-дампа отсутствуют подтверждённые идентификаторы цепочек общения; технические блоки строк используются лишь как приближение.</p>
<p>Исходные данные и завершённые версии корпуса не перезаписываются. Подготовка создаёт новые каталоги, а хеши позволяют обнаруживать последующие изменения. Тексты с непригодным форматом или неоднозначной автоматической проверкой сохраняются в карантине с причинами. Это делает отбор проверяемым: уменьшение корпуса можно объяснить конкретными правилами, а не скрытым удалением неудобных примеров.</p>
<h3>2.2. Очистка и языковая проверка</h3>
<p>Очистка включает нормализацию Unicode, декодирование HTML-сущностей, удаление служебной разметки, адресов, аккаунтных ссылок и обнаруженных шаблонов навигации. Имена, даты и пунктуация, несущие смысл текста, не удаляются безусловно. В частности, реквизиты заявления могут быть полезны для определения официально-делового стиля и не должны уничтожаться правилом очистки новостного заголовка.</p>
<p>Языковой фильтр и ограничения длины являются средствами предварительного отбора, а не экспертной разметкой. Проверка дополнительных сообщений показала, что фильтр способен пропустить близкородственный язык и формально связный материал неподходящего жанра. Поэтому автоматический этап сопровождается аудитом разметки; утверждение о полностью очищенном и экспертно проверенном корпусе пока не делается.</p>
<p>Текстовые признаки физически отделены от происхождения. Файлы train.csv, validation.csv и test.csv содержат только text и label. Адрес источника не входит в векторизацию и не передаётся encoder. Отдельные metadata и manifest связывают входы с источниками и группами. При загрузке проверяются хеши и соответствие текста и метки между файлами.</p>
<h3>2.3. Разбиение и общие входы моделей</h3>
<p>Пилотная выборка содержит 610 документов: по 122 для каждого стиля. Train содержит 370 текстов, validation и test — по 120. В каждом классе это соответственно 74, 24 и 24 наблюдения. Разделение учитывает группы дубликатов и родительские документы. Восемь шаблонов заявлений из одного учебного справочника включены только в train; их страницы не трактуются как независимые тестовые источники.</p>
<p>Для пилота из документа выбирается один ограниченный фрагмент. При подготовке используется детерминированный бюджет 40, 80 или 160 слов и ограничение 256 токенов Kaz-RoBERTa. Такой выбор уменьшает объём вычислений, однако ограничивает выводы: классифицируется фрагмент, а не обязательно весь исходный документ. Разговорный класс остаётся существенно короче остальных, что должно учитываться при интерпретации результатов.</p>
<p>Для сопоставления с mBERT сформирована производная версия text_only_v4_shared. Три обучающих фрагмента, превышавшие 512 WordPiece-токенов, сокращены на 2, 6 и 3 последних слова соответственно. Сокращение применяется к входам всех моделей. Документы, метки и разбиения сохранены; validation и test не изменились. Различие токенизаторов не приводит к скрытой обрезке только для одной сравниваемой модели.</p>
<h3>2.4. Независимая разметка</h3>
<p>Подготовлен пакет аудита из 250 текстов с предварительно сбалансированным отбором по пяти стилям. Внутри классов отбор учитывает источник, жанр и длину. Этот пакет предназначен для проверки меток корпуса; он может включать тексты, использованные при разработке, и не является новым внешним test.</p>
<p>Два разметчика получают самостоятельные локальные формы. В формах не отображаются исходная метка, источник и ответы моделей; порядок для двух форм различается. Каждый человек выбирает метку показанного фрагмента и при необходимости поясняет решение. Для смешанного текста, другого языка, недостаточного контекста и мусора пояснение обязательно.</p>
<p>Программа сопоставления проверяет хеш пакета, полный набор идентификаторов и соответствие размеченного текста. Совпавшие решения, расхождения и совпавшие нецелевые категории сохраняются раздельно. Рассчитываются доля совпадений и Cohen κ <a href="#r7">[7]</a>. Последний показатель вычисляется как κ = (pₒ − pₑ)/(1 − pₑ), где pₒ — наблюдаемое согласие, а pₑ — ожидаемое согласие при независимых решениях с заданными предельными частотами. Согласие оценивается по всем девяти вариантам решения; оно не тождественно точности модели.</p>
<div class="pending">На момент подготовки пакета реальные ответы двух независимых разметчиков не получены. Число κ и процент исправленных меток не определены. После получения ответов нужно выполнить согласование расхождений и описать квалификацию разметчиков.</div>''')
    source_diagnostic=evidence_path('reports/text_only_v4_diagnostics/diagnostics.json')
    length_diagnostic=evidence_path('reports/text_only_v4_cohorts/cohorts.json')
